sys_ux_client_script.script:
/**
 * Calls API to activate a flow in the sys_hub_flow table.
 *
 * @param {params} params
 * @param {api} params.api
 * @param {any} params.event
 * @param {any} params.imports
 * @param {ApiHelpers} params.helpers
 */
async function handler({ api, event, helpers, imports }) {
  try {
    // Use the specific flow name instead of getting it from event context
    const flowName = "SSR Subflow";

    console.log("Processing request for flow:", flowName);

    // Define API URL
    const apiUrl = "/api/985627/nsr_flow_activator/deactivate_flow";

    // API Request Payload
    const requestData = {
      data: {
        flowName: flowName
      }
    };

    console.log("Request Data:", JSON.stringify(requestData, null, 2));

    // Perform API Call
    const response = await helpers.snHttp(apiUrl, {
      method: 'PUT',
      body: requestData,
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json"
      }
    });

    console.log("API response:", response);

    if (response && response.response) {
      const responseData = response.response; // Already parsed JSON

      api.emit("NOW_UXF_PAGE#ADD_NOTIFICATIONS", {
                items: [
                    {
                        id: "alert2",
                        status: "positive",
                        icon: "info-circle-outline",
                        content: await helpers.translate("Flow activated successfully"),
                        action: { type: "dismiss" },
                    },
                ],
            });
      // Refresh the component if needed
      // api.dispatch("REFRESH_DATA");
    } else {
      const errorMessage = (response && response.error) ? response.error : 'Failed to activate flow';
      api.addErrorMessage(`Error: ${errorMessage}`);
    }
  } catch (error) {
    console.error("API Request Failed:", error);
    api.addErrorMessage(`API Request Failed: ${error.message}`);
  }
}
